data.logic_rule:
let given = (input && input.scan) || {}
let defaults = { owner: '${param.owner}', repo: '${param.repo}', ref: '${param.ref}', commits: ${param.commits}, severityFloor: '${param.severityFloor}', destination: '' }
let scan = {}
for (let k in defaults) { scan[k] = defaults[k] }
for (let k in given) {
  let v = given[k]
  if (v !== null && v !== undefined && v !== '') { scan[k] = v }
}
// `repo` is whatever the operator pasted: a bare name, owner/name, an https URL,
// an scp-style ssh remote, or a link to a file inside the repository. Reduce it
// to an owner and a name so one field accepts all of them — and let an owner
// found inside it win over the separate param, because it is the more specific
// statement of intent.
let parseRepo = function (raw, fallbackOwner) {
  let t = ('' + (raw || '')).trim()
  if (t.indexOf('://') >= 0) { t = t.substring(t.indexOf('://') + 3) }
  if (t.indexOf('@') >= 0) { t = t.substring(t.indexOf('@') + 1) }
  t = t.split('?')[0]
  t = t.split('#')[0]
  t = t.replace(':', '/')
  let parts = []
  let chunks = t.split('/')
  for (let i = 0; i < chunks.length; i++) {
    let c = chunks[i].trim()
    if (c) { parts.push(c) }
  }
  if (parts.length > 1 && parts[0].indexOf('.') >= 0) { parts.shift() }
  let owner = fallbackOwner
  let name = ''
  if (parts.length >= 2) { owner = parts[0]; name = parts[1] }
  else if (parts.length === 1) { name = parts[0] }
  if (name.length > 4 && name.substring(name.length - 4) === '.git') {
    name = name.substring(0, name.length - 4)
  }
  return { owner: owner, name: name }
}

let parsed = parseRepo(scan.repo, scan.owner)
scan.repoInput = scan.repo
scan.owner = parsed.owner
scan.repo = parsed.name

let n = parseInt('' + scan.commits, 10)
scan.commits = (n > 0 && n <= 50) ? n : 3
scan.depth = scan.commits + 1
if (!scan.destination) { scan.destination = 'venapce-scan/' + scan.owner + '/' + scan.repo }
scan.target = scan.owner + '/' + scan.repo
scan

