data.logic_rule:
let out = (input.review && input.review.output) || {}
let raw = out.findings || []
let scan = input.scan || {}
let clone = input.clone || {}

let rank = { info: 0, low: 1, medium: 2, high: 3, critical: 4 }
let floor = rank[('' + (scan.severityFloor || 'low')).toLowerCase()]
if (floor === undefined) { floor = 1 }

let text = function (v) { return (v === null || v === undefined) ? '' : ('' + v) }
let slug = function (v) { return text(v).toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+/, '').replace(/-+$/, '') }

let commitRows = []
let visit = function (v, depth) {
  if (v === null || v === undefined || depth > 6) { return }
  if (Array.isArray(v)) { for (let i = 0; i < v.length; i++) { visit(v[i], depth + 1) } return }
  if (typeof v !== 'object') { return }
  if (v.sha) { commitRows.push(v) }
  for (let k in v) { visit(v[k], depth + 1) }
}
visit(input.commits, 0)

let commitMetaFor = function (sha) {
  let want = text(sha)
  if (!want) { return null }
  for (let i = 0; i < commitRows.length; i++) {
    let row = commitRows[i]
    let got = text(row.sha)
    if (got && (got === want || got.indexOf(want) === 0 || want.indexOf(got) === 0)) {
      let c = row.commit || {}
      let author = c.author || {}
      return {
        sha: got,
        message: text(c.message).split('\n')[0],
        author: text(author.name || (row.author && row.author.login)),
        date: text(author.date),
        url: text(row.html_url || row.url)
      }
    }
  }
  return null
}

let seen = {}
let findings = []
for (let i = 0; i < raw.length; i++) {
  let f = raw[i] || {}
  let title = text(f.title)
  if (!title) { continue }
  let sev = text(f.severity).toLowerCase()
  if (rank[sev] === undefined) { sev = 'info' }
  if (rank[sev] < floor) { continue }
  let file = text(f.file)
  let line = parseInt('' + f.line, 10)
  if (!(line > 0)) { line = 0 }
  let commit = text(f.commit) || text(clone.commit)
  let fingerprint = 'github:' + scan.target + ':' + file + ':' + line + ':' + slug(title)
  if (seen[fingerprint]) { continue }
  seen[fingerprint] = true
  findings.push({
    title: title,
    severity: sev,
    severityRank: rank[sev],
    confidence: text(f.confidence).toLowerCase() || 'medium',
    category: slug(f.category) || 'other',
    summary: text(f.summary),
    file: file,
    line: line,
    commit: commit,
    shortCommit: commit.substring(0, 7),
    commitMeta: commitMetaFor(commit),
    evidence: text(f.evidence),
    remediation: text(f.remediation),
    falsePositiveRisk: text(f.falsePositiveRisk).toLowerCase() || 'unknown',
    fingerprint: fingerprint,
    where: file ? (file + (line > 0 ? (':' + line) : '')) : scan.target
  })
}
findings.sort(function (a, b) { return b.severityRank - a.severityRank })

// Shape each finding into the values the Cast node lifts into Stage columns. The
// Cast node can only lift a path or write a literal — it cannot compute — so
// everything that needs computing is done here, and the mapping stays a mapping.
let review = input.review || {}

// A Stage title is read in a list, so it is clamped; the model's own wording is
// kept in full on the row's `data.title`.
let clamp = function (v, max) {
  let t = text(v)
  return t.length > max ? (t.substring(0, max - 1) + '\u2026') : t
}

// Which model actually did the work. `review.model` is whichever model the last
// message used, and Claude Code bills small side-calls to a cheaper one — so the
// usage table is the honest record of what reviewed this repository.
let models = []
let usage = review.usage || {}
for (let m in usage) { models.push(m) }

let repo = {
  owner: scan.owner,
  name: scan.repo,
  target: scan.target,
  branch: clone.branch || '',
  url: clone.url || ''
}

for (let i = 0; i < findings.length; i++) {
  let f = findings[i]
  f.stageTitle = '[' + f.severity + '] ' + clamp(f.title, 96) + ' \u2014 ' + scan.target + '@' + f.shortCommit
  f.stageRef = {
    producer: 'claude-agent',
    model: review.model || '',
    models: models,
    sessionId: review.sessionId || '',
    fingerprint: f.fingerprint,
    repo: repo,
    commit: f.commit,
    commitMeta: f.commitMeta || null,
    commitsReviewed: scan.commits,
    workspace: review.workspace || clone.path || ''
  }
  f.stageData = {
    title: f.title,
    severity: f.severity,
    confidence: f.confidence,
    category: f.category,
    summary: f.summary,
    file: f.file,
    line: f.line,
    where: f.where,
    commit: f.commit,
    evidence: f.evidence,
    remediation: f.remediation
  }
  f.stageMeta = {
    falsePositiveRisk: f.falsePositiveRisk,
    severityRank: f.severityRank,
    severityFloor: scan.severityFloor || '',
    review: {
      state: review.state || '',
      turns: review.turns || 0,
      costUsd: review.costUsd || 0,
      observedAt: review.observedAt || 0
    }
  }
}
findings

let scan = input.scan || {}
let clone = input.clone || {}
let r = input.review || {}
let out = r.output || {}
let reviewSummary = {
  verdict: out.verdict || 'clean',
  target: scan.target || '',
  branch: clone.branch || '',
  head: clone.commit || '',
  commitsReviewed: scan.commits || 0,
  severityFloor: scan.severityFloor || '',
  staged: 0,
  note: 'No security issue at or above the severity floor in the reviewed commits — nothing was written to Stage.',
  turns: r.turns || 0,
  costUsd: r.costUsd || 0
}
reviewSummary

let r = input.review || {}
let reviewProblem = {
  state: r.state || 'unknown',
  reason: r.error || (r.limit && r.limit.reason) || '',
  text: r.text || '',
  sessionId: r.sessionId || '',
  workspace: r.workspace || '',
  advice: 'Run the review node again to continue the same session, or raise Max turns / Max spend on it.'
}
reviewProblem
